#include <stdio.h>
#include <stdlib.h>

/* prime report
 * Primes are generated by dividing each odd candidate only by the primes
 * already found, and twin pairs are spotted while the list is being built. */

#define N 200

/* smallest divisor of value that is greater than 1 (value itself if prime) */
int smallest_factor(int value)
{
    int trial = 3;

    if (value % 2 == 0)
        return 2;
    while (trial * trial <= value) {
        if (value % trial == 0)
            return trial;
        trial += 2;
    }
    return value;
}

/* 1 when one of the known primes (only those up to sqrt(candidate)) divides it */
int divisible_by_known(const int *known, int used, int candidate)
{
    int idx = 0;

    while (idx < used && known[idx] * known[idx] <= candidate) {
        if (candidate % known[idx] == 0)
            return 1;
        idx++;
    }
    return 0;
}

/* stores a malloc'd array of the primes <= limit in *out; returns the count, -1 if no memory */
int generate_primes(int limit, int **out, int *twin_total)
{
    int *store = malloc(sizeof(int) * (limit / 2 + 2));
    int used = 0;
    int candidate;

    *twin_total = 0;
    if (store == NULL)
        return -1;
    if (limit >= 2)
        store[used++] = 2;
    /* even numbers above 2 can never be prime, so step by 2 */
    for (candidate = 3; candidate <= limit; candidate += 2) {
        if (!divisible_by_known(store, used, candidate)) {
            if (store[used - 1] == candidate - 2) {
                printf("    twin #%d: %d and %d\n", *twin_total + 1, candidate - 2, candidate);
                (*twin_total)++;
            }
            store[used++] = candidate;
        }
    }
    *out = store;
    return used;
}

/* prints one query line; composites also show their smallest factorisation */
void describe(int value)
{
    int f;

    if (value < 2) {
        printf("%6d : not prime (less than 2)\n", value);
        return;
    }
    f = smallest_factor(value);
    if (f == value)
        printf("%6d : PRIME\n", value);
    else
        printf("%6d : composite = %d x %d\n", value, f, value / f);
}

int main(void)
{
    const int queries[] = {2, 57, 97, 143, 199, 1009, 1024};
    const int query_count = (int)(sizeof queries / sizeof queries[0]);
    int *primes = NULL;
    int twins = 0;
    int total, j;

    printf("Report for N = %d\n", N);
    printf("  twin pairs found while scanning:\n");
    total = generate_primes(N, &primes, &twins);
    if (total < 0) {
        printf("out of memory\n");
        return 1;
    }
    printf("  prime count : %d\n", total);
    printf("  largest     : %d\n", primes[total - 1]);
    printf("  primes      :");
    for (j = 0; j < total; j++)
        printf("%s%3d", (j % 12 == 0) ? "\n    " : " ", primes[j]);
    printf("\n  twin pairs  : %d\n", twins);
    printf("Queries:\n");
    for (j = 0; j < query_count; j++)
        describe(queries[j]);
    free(primes);
    return 0;
}
